import React, { useEffect, useMemo, useState } from 'react';
import { Box } from '@mui/material';
import AnimatedPage from '../../layouts/AnimatedPage';
import {
  useGetSalesDetailsByOrderIdQuery,
  useGetUserQuery,
} from '../posApi';
import { ISalesReceipt } from '../../core/Interface/sale.interface';
import { useAppDispatch } from '../../store/hooks';
import {
  addFinalSummaryState,
  removeBasket,
} from './store/BasketSlice';
import { generateString } from '../../core/utils';
import { IUserInfo } from '../../core/Interface/user.interface';
import { ResContext } from './context/ResContext';
import ResLeft from './components/ResLeft/Index';
import ResRight from './components/ResRight/Index';
import useSales from './useSales';

const RestaurantSales = () => {
  const { selectItem, paymentStatus } = useSales();
  const dispatch = useAppDispatch();
  const { data: companyData } = useGetUserQuery();

  const [invoiceId, setInvoiceId] = useState<string>('');
  const [salesList, setSalesList] = useState<ISalesReceipt | null>(null);
  const [selectedBillId, setSelectedBillId] = useState<string>('');

  const {
    data: salesDetailsData,
    isLoading: isLoadingDetails,
    isFetching: isFetchingDetails,
  } = useGetSalesDetailsByOrderIdQuery(invoiceId.split('_')[0], {
    skip: !invoiceId,
  });

  useEffect(() => {
    if (salesDetailsData?.data) {
      setSalesList(salesDetailsData.data as ISalesReceipt);
    }
  }, [salesDetailsData?.data]);

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const handleBillSelect = (billId: string) => {
    if (selectItem && Object.keys(selectItem).length > 0) {
      dispatch(removeBasket());
    }
    setSelectedBillId(billId);
    if (invoiceId === billId) {
      setInvoiceId(billId + '_' + generateString(5));
    } else {
      setInvoiceId(billId);
    }
    if (!paymentStatus) {
      dispatch(addFinalSummaryState({ finalSummaryStare: true }));
    }
  };

  const clearSalesItems = () => {
    setSalesList(null);
    setSelectedBillId('');
    setInvoiceId('');
  };

  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, []);

  return (
    <AnimatedPage>
      <ResContext.Provider
        value={{
          salesList,
          selectedBillId,
          invoiceId,
          isLoadingDetails,
          isFetchingDetails,
          onBillSelect: handleBillSelect,
          onClear: clearSalesItems,
          currencyCode,
        }}
      >
        <Box sx={{ height: '100vh', overflow: 'hidden' }}>
          <ResLeft />
          <ResRight />
        </Box>
      </ResContext.Provider>
    </AnimatedPage>
  );
};

export default RestaurantSales;
