import { Box, Divider, Grid, Typography } from '@mui/material';
import React from 'react';
import { appColors, HEADER_GRADIENT } from '../../../../theme/appColors';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import useSales from '../../useSales';
import { useResContext } from '../../context/ResContext';

const row = (label: string, value: string) => (
  <Grid
    container
    sx={{ py: '3px' }}
  >
    <Grid
      item
      xs={6}
    >
      <Typography
        sx={{
          fontSize: 12,
          fontWeight: 600,
          color: appColors.white,
          textTransform: 'uppercase',
          letterSpacing: '0.4px',
        }}
      >
        {label}
      </Typography>
    </Grid>
    <Grid
      item
      xs={6}
    >
      <Typography
        align="right"
        sx={{
          fontSize: 12,
          fontWeight: 600,
          color: appColors.white,
          fontVariantNumeric: 'tabular-nums',
        }}
      >
        {value}
      </Typography>
    </Grid>
  </Grid>
);

const ResSummary = () => {
  const { calculateSummary, paymentStatus } = useSales();
  const { salesList, currencyCode } = useResContext();

  const displaySub = paymentStatus && salesList ? salesList.subTotal : calculateSummary.subTotal;
  const displayDis = paymentStatus && salesList ? salesList.discount : calculateSummary.discount;
  const displayTotal = paymentStatus && salesList ? salesList.total : calculateSummary.total;

  return (
    <Box
      sx={{
        background: HEADER_GRADIENT,
        px: '14px',
        pt: '10px',
        pb: '12px',
      }}
    >
      {row('Subtotal', getPriceFormatWithoutCurrency(displaySub))}
      {row('Discount', `- ${getPriceFormatWithoutCurrency(displayDis)}`)}

      <Divider sx={{ borderColor: 'rgba(255,255,255,0.2)', my: '8px' }} />

      <Grid
        alignItems="center"
        container
      >
        <Grid
          item
          xs={5}
        >
          <Typography
            sx={{
              fontSize: 13,
              fontWeight: 800,
              color: appColors.white,
              textTransform: 'uppercase',
              letterSpacing: '0.6px',
            }}
          >
            Net Total
          </Typography>
          {currencyCode && (
            <Typography sx={{ fontSize: 10, color: appColors.white, fontWeight: 500 }}>
              {currencyCode}
            </Typography>
          )}
        </Grid>
        <Grid
          item
          xs={7}
        >
          <Typography
            align="right"
            sx={{
              fontSize: 16,
              fontWeight: 900,
              color: appColors.white,
              fontVariantNumeric: 'tabular-nums',
              lineHeight: 1,
            }}
          >
            {getPriceFormatWithoutCurrency(displayTotal)}
          </Typography>
        </Grid>
      </Grid>
    </Box>
  );
};

export default React.memo(ResSummary);
