import React, { createContext, useContext } from 'react';
import { ISalesReceipt } from '../../../core/Interface/sale.interface';

interface ResContextType {
  salesList: ISalesReceipt | null;
  selectedBillId: string;
  invoiceId: string;
  isLoadingDetails: boolean;
  isFetchingDetails: boolean;
  onBillSelect: (billId: string) => void;
  onClear: () => void;
  currencyCode: string;
}

const defaultCtx: ResContextType = {
  salesList: null,
  selectedBillId: '',
  invoiceId: '',
  isLoadingDetails: false,
  isFetchingDetails: false,
  onBillSelect: () => {},
  onClear: () => {},
  currencyCode: '',
};

export const ResContext = createContext<ResContextType>(defaultCtx);
export const useResContext = () => useContext(ResContext);
