import { Box, Backdrop, CircularProgress } from '@mui/material';
import React from 'react';
import ResCategory from './ResCategory';
import ResActionRow from './ResActionRow';
import ResPendingBills from './ResPendingBills';
import ResPaymentPanel from './ResPaymentPanel';
import useSales from '../../useSales';
import { useResContext } from '../../context/ResContext';

const ResRight = () => {
  const { paymentStatus } = useSales();
  const { isLoadingDetails, isFetchingDetails } = useResContext();

  return (
    <Box
      sx={{
        '--tile-h': 'calc((100vh - 124px) / 7)',
        position: 'fixed',
        left: 'calc(33.333% + 4px)',
        right: '4px',
        height: 'calc(100vh - 96px)',
        overflow: 'hidden',
        zIndex: 5,
        display: 'flex',
        flexDirection: 'column',
        gap: '3px',
        pt: '2px',
        pb: '8px',
      }}
    >
      <Backdrop
        open={isLoadingDetails || isFetchingDetails}
        sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 1 }}
      >
        <CircularProgress color="inherit" />
      </Backdrop>

      {!paymentStatus ? (
        <>
          <Box sx={{ flex: '0 0 auto' }}>
            <ResCategory />
          </Box>
          <Box sx={{ flex: '0 0 auto' }}>
            <ResActionRow />
          </Box>
          <Box sx={{ flex: '0 0 auto' }}>
            <ResPendingBills />
          </Box>
        </>
      ) : (
        <Box sx={{ flex: '0 0 auto' }}>
          <ResPaymentPanel />
        </Box>
      )}
    </Box>
  );
};

export default React.memo(ResRight);
