import { Box, Chip, Grid, Typography } from '@mui/material';
import React from 'react';
import { useSelector } from 'react-redux';
import { selectBasketItems, selectMaxDiscountAmount } from '../../store/BasketSelector';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import { appColors } from '../../../../theme/appColors';
import { useResContext } from '../../context/ResContext';
import { IAddCount } from '../../../../core/Interface/property.interface';
import { ISalesItem } from '../../../../core/Interface/sale.interface';
import AddItemCount from '../AddItemCount';

const profileLabel = (name: string, muted = false) => (
  <Typography
    sx={{
      fontSize: 11,
      fontWeight: 500,
      color: muted ? appColors.darkGray[40] : appColors.royalBlue[100],
      lineHeight: 1.2,
    }}
  >
    {name}
  </Typography>
);

const profileValue = (val: string, muted = false) => (
  <Typography
    align="right"
    sx={{
      fontSize: 11,
      color: muted ? appColors.darkGray[40] : appColors.royalBlue[80],
      fontVariantNumeric: 'tabular-nums',
    }}
  >
    {val}
  </Typography>
);

const ResBasketItems = () => {
  const { salesList } = useResContext();
  const basketItems = useSelector(selectBasketItems);
  const maxDiscountAmount = useSelector(selectMaxDiscountAmount);
  const [openProductCount, setOpenProductCount] = React.useState(false);
  const [itemCountProb, setItemCountProb] = React.useState<IAddCount>();

  const salesItems: ISalesItem[] = salesList?.items ?? [];
  const isEmpty = salesItems.length === 0 && basketItems.length === 0;

  if (isEmpty) {
    return (
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          opacity: 0.35,
          py: 4,
        }}
      >
        <Typography sx={{ fontSize: 13, color: appColors.royalBlue[60] }}>
          No items added yet
        </Typography>
      </Box>
    );
  }

  const openCount = (item: {
    id: string;
    code: string;
    count: number;
    unitPrice: number;
    defaultDiscountAmount?: number;
    isDiscountPercentage?: boolean;
  }) => {
    setItemCountProb({
      id: item.id,
      code: item.code,
      count: item.count,
      unitPrice: item.unitPrice,
      discountValue: item.defaultDiscountAmount,
      isDiscountPercentage: item.isDiscountPercentage,
    });
    setOpenProductCount(true);
  };

  return (
    <Box sx={{ p: '4px 8px 0 8px' }}>
      {/* Loaded sale items (greyed) */}
      {salesItems.map((item: ISalesItem) => (
        <Grid
          alignItems="center"
          container
          flexWrap="nowrap"
          key={'sale-' + item.productId}
          spacing={1}
          sx={{
            py: '6px',
            px: '4px',
            borderBottom: `1px solid ${appColors.darkGray[10]}`,
            opacity: 0.6,
          }}
        >
          <Grid
            item
            md={3}
            xs={3}
          >
            {profileLabel(item.productName ?? '', true)}
          </Grid>
          <Grid
            item
            md={2}
            xs={2}
          >
            <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
              <Chip
                label={item.qty}
                size="small"
                sx={{
                  height: 20,
                  fontSize: 11,
                  fontWeight: 700,
                  backgroundColor: appColors.darkGray[40],
                  color: appColors.white,
                  '& .MuiChip-label': { px: '6px' },
                }}
              />
            </Box>
          </Grid>
          <Grid
            item
            md={3}
            xs={3}
          >
            {profileValue(getPriceFormatWithoutCurrency(item.unitPrice), true)}
          </Grid>
          <Grid
            item
            md={2}
            xs={2}
          >
            {profileValue(getPriceFormatWithoutCurrency(item.discount ?? 0), true)}
          </Grid>
          <Grid
            item
            md={2}
            xs={2}
          >
            {profileValue(getPriceFormatWithoutCurrency(item.unitPrice * item.qty), true)}
          </Grid>
        </Grid>
      ))}

      {/* Basket items */}
      {basketItems
        .slice()
        .reverse()
        .map((item) => {
          const discAmt = item.defaultDiscountAmount ?? 0;
          const lineTotal = (
            (item.unitPrice -
              (item.isDiscountPercentage
                ? (item.unitPrice / 100) * discAmt
                : discAmt)) *
            item.count
          ).toFixed(2);
          return (
            <Grid
              alignItems="center"
              container
              flexWrap="nowrap"
              key={item.id}
              onClick={() =>
                openCount({
                  id: item.id,
                  code: item.code,
                  count: item.count,
                  unitPrice: item.unitPrice,
                  defaultDiscountAmount: item.defaultDiscountAmount,
                  isDiscountPercentage: item.isDiscountPercentage,
                })
              }
              spacing={1}
              sx={{
                py: '6px',
                px: '4px',
                cursor: 'pointer',
                borderBottom: `1px solid ${appColors.darkGray[10]}`,
                borderRadius: '6px',
                transition: 'background 0.15s',
                '&:hover': { backgroundColor: appColors.reflexBlue[10] },
              }}
            >
              <Grid
                item
                md={3}
                xs={3}
              >
                {profileLabel(item.name)}
              </Grid>
              <Grid
                item
                md={2}
                xs={2}
              >
                <Box sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                  <Chip
                    label={item.count}
                    size="small"
                    sx={{
                      height: 20,
                      fontSize: 11,
                      fontWeight: 700,
                      backgroundColor: appColors.reflexBlue[100],
                      color: appColors.white,
                      '& .MuiChip-label': { px: '6px' },
                    }}
                  />
                </Box>
              </Grid>
              <Grid
                item
                md={3}
                xs={3}
              >
                {profileValue(getPriceFormatWithoutCurrency(item.unitPrice))}
              </Grid>
              <Grid
                item
                md={2}
                xs={2}
              >
                {profileValue(
                  `${getPriceFormatWithoutCurrency(discAmt)}${item.isDiscountPercentage ? '%' : ''}`
                )}
              </Grid>
              <Grid
                item
                md={2}
                xs={2}
              >
                {profileValue(lineTotal)}
              </Grid>
            </Grid>
          );
        })}

      {openProductCount && (
        <AddItemCount
          handleCloseDialog={() => setOpenProductCount(false)}
          item={itemCountProb}
          maxDiscountAmount={maxDiscountAmount}
          openModel={openProductCount}
          title="Update product count"
        />
      )}
    </Box>
  );
};

export default React.memo(ResBasketItems);
