import React from 'react';
import { Button } from '@mui/material';
import Person3Icon from '@mui/icons-material/Person3';
import { useSelector } from 'react-redux';
import { addCustomer } from '../../store/BasketSelector';
import AddMobile from '../AddMobile';

const ResCustomer = () => {
  const customer = useSelector(addCustomer);
  const hasMobile = Boolean(customer?.mobile);
  const [openAddMobile, setOpenAddMobile] = React.useState(false);

  return (
    <>
      <Button
        fullWidth
        onClick={() => setOpenAddMobile(true)}
        startIcon={hasMobile ? <Person3Icon sx={{ color: '#dc2626' }} /> : undefined}
        sx={{
          justifyContent: 'flex-start',
          borderRadius: '8px',
          border: '1px solid #e0e0e0',
          color: '#0F1D4D',
          fontWeight: 700,
          fontSize: 13,
          py: 0.8,
          px: 2,
          backgroundColor: hasMobile ? '#fef2f2' : 'transparent',
          '&:hover': { backgroundColor: '#e6e8f3' },
          textTransform: 'none',
        }}
        variant="outlined"
      >
        {hasMobile ? (customer.mobile ?? 'Customer') : 'Customer'}
      </Button>
      {openAddMobile && (
        <AddMobile
          customers=""
          handleCloseDialog={() => setOpenAddMobile(false)}
          openModel={openAddMobile}
          title="Add Customer"
        />
      )}
    </>
  );
};

export default React.memo(ResCustomer);
