import {
  Box,
  Grid,
  IconButton,
  Paper,
  Skeleton,
  Stack,
  styled,
  Typography,
} from '@mui/material';
import React, { useMemo, useState } from 'react';
import { appColors } from '../../../../theme/appColors';
import { useGetAllProductQuery } from '../../../posApi';
import { IProduct, IProductData } from '../../../../core/Interface/product.interface';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import ResProducts from './ResProducts';
import { useAppDispatch } from '../../../../store/hooks';
import { BasketItem, addItem } from '../../store/BasketSlice';
import AlertPopup from '../Kgpopup';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  color: theme.palette.text.secondary,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const CAT_MAX_COUNT_PER_ROW = 7;

const ResCategory = () => {
  const dispatch = useAppDispatch();
  const { data, isLoading } = useGetAllProductQuery({
    pageIndex: 0,
    pageSize: 1000,
    searchText: '',
  });

  const productDataMemo = useMemo(() => data?.data as IProduct, [data?.data]);

  const groupedData = useMemo(() => {
    const grouped: Record<string, IProductData[]> = {};
    if (!isLoading && productDataMemo?.records) {
      productDataMemo.records.forEach((re) => {
        if (!grouped[re.categoryName]) grouped[re.categoryName] = [];
        grouped[re.categoryName].push(re);
      });
    }
    return grouped;
  }, [isLoading, productDataMemo]);

  const [catNextPage, setCatNextPage] = useState(0);
  const [selectCat, setSelectCat] = useState('');
  const [openShowPopup, setOpenShowPopup] = React.useState(false);
  const [selectedProduct, setSelectedProduct] = React.useState<IProductData | null>(null);

  const catPageWiseData = useMemo(() => {
    const cat = Object.keys(groupedData).sort((a, b) =>
      a.toLowerCase().localeCompare(b.toLowerCase())
    );
    const pageStaticVal = catNextPage * CAT_MAX_COUNT_PER_ROW;
    const catList = cat.slice(pageStaticVal, pageStaticVal + CAT_MAX_COUNT_PER_ROW);
    return { catList, catTotalRecords: cat.length, allProducts: Object.values(groupedData).flat() };
  }, [catNextPage, groupedData]);

  const totalPages = Math.ceil(catPageWiseData.catTotalRecords / CAT_MAX_COUNT_PER_ROW);

  const addItemToBasket = (item: IProductData) => {
    if (item.isKgOrLitre) {
      setSelectedProduct(item);
      setOpenShowPopup(true);
    } else {
      const basketItem: BasketItem = { ...item, count: 1 };
      dispatch(addItem(basketItem));
    }
  };

  const handleKgAdd = (calculatedValue: number | null, inputCount: number) => {
    if (selectedProduct && calculatedValue !== null) {
      const basketItem: BasketItem = { ...selectedProduct, count: inputCount };
      dispatch(addItem(basketItem));
      setOpenShowPopup(false);
    }
  };

  const selectedProducts =
    selectCat === '' ? catPageWiseData.allProducts : groupedData[selectCat] ?? [];

  return (
    <Box>
      {/* Category tiles row */}
      <Grid
        container
        spacing={1}
        sx={{ cursor: 'pointer' }}
      >
        {!isLoading &&
          catPageWiseData.catList.map((item) => (
            <Grid
              item
              key={item + '-cat'}
              md={1.5}
              sm={4}
              xs={4}
            >
              <Item
                onClick={() => setSelectCat(selectCat === item ? '' : item)}
                sx={{
                  background:
                    selectCat === item
                      ? 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)'
                      : 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)',
                  border: selectCat === item ? '2px solid #99f6e4' : '2px solid transparent',
                  boxShadow:
                    selectCat === item ? '0 4px 14px rgba(20,30,85,0.35)' : 'none',
                }}
              >
                <Stack
                  alignItems="center"
                  direction="column"
                >
                  <Typography
                    sx={{
                      fontWeight: 700,
                      fontSize: 11,
                      color: selectCat === item ? appColors.white : '#0F1D4D',
                      textAlign: 'center',
                      letterSpacing: '0.3px',
                      lineHeight: 1.2,
                      px: 0.5,
                    }}
                  >
                    {item}
                  </Typography>
                </Stack>
              </Item>
            </Grid>
          ))}

        {/* Empty filler tiles */}
        {!isLoading &&
          catPageWiseData.catList.length < CAT_MAX_COUNT_PER_ROW &&
          Array.from(
            Array(CAT_MAX_COUNT_PER_ROW - catPageWiseData.catList.length).keys()
          ).map((k) => (
            <Grid
              item
              key={'-filler-cat-' + k}
              md={1.5}
              sm={4}
              xs={4}
            >
              <Item
                sx={{
                  background: 'rgba(148,163,184,0.15)',
                  cursor: 'default',
                  boxShadow: 'none',
                }}
              />
            </Grid>
          ))}

        {/* Pagination arrows */}
        {!isLoading && (
          <Grid
            item
            key="ArrowIcons-cat"
            md={1.5}
            sm={4}
            xs={4}
          >
            <Item
              sx={{
                background: 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)',
                cursor: 'default',
              }}
            >
              <Grid container>
                <Grid
                  item
                  sm={6}
                >
                  <IconButton
                    disabled={catNextPage <= 0}
                    onClick={() => setCatNextPage((cur) => cur - 1)}
                    size="small"
                    sx={{
                      color: appColors.white,
                      '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                    }}
                  >
                    <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
                <Grid
                  item
                  sm={6}
                >
                  <IconButton
                    disabled={catNextPage >= totalPages - 1}
                    onClick={() => setCatNextPage((cur) => cur + 1)}
                    size="small"
                    sx={{
                      color: appColors.white,
                      '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                    }}
                  >
                    <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
              </Grid>
            </Item>
          </Grid>
        )}

        {/* Loading skeletons */}
        {isLoading &&
          Array.from(Array(CAT_MAX_COUNT_PER_ROW + 1).keys()).map((item) => (
            <Grid
              item
              key={'_load_cat' + item}
              md={1.5}
              sm={4}
              xs={4}
            >
              <Skeleton
                height={'var(--tile-h)'}
                sx={{ borderRadius: '10px' }}
                variant="rectangular"
              />
            </Grid>
          ))}
      </Grid>

      {/* Product tiles */}
      <ResProducts
        isLoading={isLoading}
        onAddItem={addItemToBasket}
        products={selectedProducts.filter((p) => p.isEnabled)}
        selectCat={selectCat}
      />

      {selectedProduct && selectedProduct.isKgOrLitre && (
        <AlertPopup
          handleAdd={handleKgAdd}
          handleCloseAlert={() => {
            setOpenShowPopup(false);
            setSelectedProduct(null);
          }}
          key={selectedProduct.id}
          open={openShowPopup}
          unitPrice={selectedProduct.unitPrice ?? 0}
        />
      )}
    </Box>
  );
};

export default React.memo(ResCategory);
