/* eslint-disable @typescript-eslint/no-explicit-any */
import { combineReducers } from '@reduxjs/toolkit';
import { AuthReducer } from '../page/Auth/AuthSlice';
import { posApi } from '../page/posApi';
import { POSReducer } from './posSlice';
import { PurchaseBasketReducer } from '../page/Purchase/store/BasketSlice';
import { RestaurantBasketReducer } from '../page/ResturantSales/store/BasketSlice';
import { SalesRichBasketReducer } from '../page/SalesRich/store/SalesRichBasketSlice';
import { JewelBasketReducer } from '../page/Jewellery/store/BasketSlice';
import { JewelPreOrderBasketReducer } from '../page/PreOrderSale/store/BasketSlice';
import { purchaseJewelBasketReducer } from '../page/PurchaseJewellery/store/BasketSlice';


export const ROOT_ACTIONS = {
  logout: 'logout',
};

// Define the Reducers that will always be present in the application
const staticReducers = {
  [posApi.reducerPath]: posApi.reducer,
  auth: AuthReducer,
  salesRichBasket: SalesRichBasketReducer,
  posStore: POSReducer,
  purchaseBasket: PurchaseBasketReducer,
  restaurantBasket: RestaurantBasketReducer,
  jewelBasket: JewelBasketReducer,
  jewelPreOrderBasket: JewelPreOrderBasketReducer,
  purchaseJewelBasket: purchaseJewelBasketReducer,

};

const createReducer = (asyncReducers?: any) => (state: any, action: any) => {
  let combinedReducer;
  if (asyncReducers) {
    combinedReducer = combineReducers({
      ...staticReducers,
      ...asyncReducers,
    });
  } else {
    // Else just combine the static reducers
    combinedReducer = combineReducers({
      ...staticReducers,
    });
  }

  /**
   * Reset the redux store when user logged out
   */
  if (action.type === ROOT_ACTIONS.logout) {
    state = undefined;
  }

  return combinedReducer
    ? combinedReducer(state, action as never)
    : { ...state };
};

createReducer();

export default createReducer;
