import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React, { useEffect, useMemo, useState } from 'react';
import { appColors } from '../../../../theme/appColors';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import useSales from '../../useSales';
import {
  addFinalSummaryState,
  addPaymentMethod,
  addReceivedMoney,
  addReturnAmount,
} from '../../store/BasketSlice';
import { useAppDispatch } from '../../../../store/hooks';
import { useSelector } from 'react-redux';
import { selectPaymentMethod } from '../../store/BasketSelector';
import { useResContext } from '../../context/ResContext';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import PaymentsIcon from '@mui/icons-material/Payments';
import ReceiptIcon from '@mui/icons-material/Receipt';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const QUICK_AMOUNTS = [5, 10, 20, 50, 100, 500, 1000, 5000];
const NUMPAD_KEYS = ['9', '8', '7', '6', '5', '4', '3', '2', '1', '00', '0', '.'];

const ResPaymentPanel = () => {
  const dispatch = useAppDispatch();
  const { salesList, currencyCode } = useResContext();
  const { calculateSummary } = useSales();
  const paymentMethod = useSelector(selectPaymentMethod);

  const total = salesList?.total ?? calculateSummary.total;

  const [receivedCache, setReceivedCache] = useState(0);
  const [returnCache, setReturnCache] = useState(0);
  const [enterAmount, setEnterAmount] = useState('');

  useEffect(() => {
    dispatch(addPaymentMethod('Cash'));
    setReceivedCache(0);
  }, []);

  useEffect(() => {
    dispatch(addReceivedMoney(receivedCache));
    dispatch(addReturnAmount(returnCache));
  }, [receivedCache, returnCache]);

  const handlePaymentMethodSelect = (method: string) => {
    dispatch(addPaymentMethod(method));
    if (method === 'Card' || method === 'Cheque') {
      setReceivedCache(total);
    } else {
      setReceivedCache(0);
    }
  };

  const addDigit = (digit: string) => {
    setEnterAmount((prev) => prev + digit);
  };

  const acceptAmount = () => {
    setReceivedCache(Number(enterAmount) || 0);
    setEnterAmount('');
  };

  const clearAmount = () => {
    setEnterAmount('');
    setReceivedCache(0);
    setReturnCache(0);
  };

  const balance = receivedCache - total + returnCache;

  const payMethodTile = (
    method: string,
    icon: React.ReactNode,
    gradient: string
  ) => (
    <Grid
      item
      md={1.5}
      sm={4}
      xs={4}
    >
      <Item
        onClick={() => handlePaymentMethodSelect(method)}
        sx={{
          background: paymentMethod === method ? 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)' : gradient,
          border: paymentMethod === method ? '2px solid #99f6e4' : '2px solid transparent',
          boxShadow: paymentMethod === method ? '0 4px 14px rgba(20,30,85,0.35)' : 'none',
        }}
      >
        <Stack
          alignItems="center"
          direction="column"
        >
          {React.cloneElement(icon as React.ReactElement, {
            sx: { fontSize: 26, color: paymentMethod === method ? appColors.white : '#0F1D4D' },
          })}
          <Typography
            sx={{
              fontWeight: 700,
              fontSize: 11,
              color: paymentMethod === method ? appColors.white : '#0F1D4D',
              mt: '2px',
            }}
          >
            {method}
          </Typography>
        </Stack>
      </Item>
    </Grid>
  );

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
      {/* Row 1: Back + Payment methods */}
      <Grid
        container
        spacing={1}
      >
        {/* Back */}
        <Grid
          item
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={() => dispatch(addFinalSummaryState({ finalSummaryStare: false }))}
            sx={{ background: 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)' }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <ArrowBackIosNewIcon sx={{ fontSize: 26, color: '#1E3A8A' }} />
              <Typography sx={{ fontWeight: 700, fontSize: 11, color: '#0F1D4D', mt: '2px' }}>
                Back
              </Typography>
            </Stack>
          </Item>
        </Grid>

        {/* Payment methods */}
        {payMethodTile(
          'Cash',
          <PaymentsIcon />,
          'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)'
        )}
        {payMethodTile(
          'Card',
          <CreditCardIcon />,
          'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)'
        )}
        {payMethodTile(
          'Cheque',
          <ReceiptIcon />,
          'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)'
        )}

        {/* Empty fillers */}
        {[1, 2, 3, 4].map((k) => (
          <Grid
            item
            key={'pay-filler-' + k}
            md={1.5}
            sm={4}
            xs={4}
          >
            <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
          </Grid>
        ))}
      </Grid>

      {/* Row 2: Amount summary tiles */}
      <Grid
        container
        spacing={1}
      >
        {/* Total Due */}
        <Grid
          item
          md={3}
          xs={6}
        >
          <AmountTile
            color="#DC2626"
            currencyCode={currencyCode}
            label="Total Due"
            value={total}
          />
        </Grid>
        {/* Received */}
        <Grid
          item
          md={3}
          xs={6}
        >
          <AmountTile
            color="#16a34a"
            currencyCode={currencyCode}
            label="Received"
            value={receivedCache}
          />
        </Grid>
        {/* Return */}
        <Grid
          item
          md={3}
          xs={6}
        >
          <AmountTile
            color="#d97706"
            currencyCode={currencyCode}
            label="Return"
            value={returnCache}
          />
        </Grid>
        {/* Balance */}
        <Grid
          item
          md={3}
          xs={6}
        >
          <AmountTile
            color={balance < 0 ? appColors.carmineRed[120] : balance > 0 ? appColors.darkGreen[80] : '#0F1D4D'}
            currencyCode={currencyCode}
            label="Balance"
            value={balance}
          />
        </Grid>
      </Grid>

      {/* Row 3: Quick-pick amounts */}
      <Grid
        container
        spacing={1}
      >
        {QUICK_AMOUNTS.map((amt) => (
          <Grid
            item
            key={'quick-' + amt}
            md={1.5}
            sm={3}
            xs={3}
          >
            <Item
              onClick={() => setReceivedCache(amt)}
              sx={{
                background: 'linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%)',
                border: '1px solid #bbf7d0',
              }}
            >
              <Typography sx={{ fontWeight: 800, fontSize: 14, color: '#14532d' }}>
                {amt}
              </Typography>
            </Item>
          </Grid>
        ))}
      </Grid>

      {/* Row 4: Enter amount display + numpad */}
      <Grid
        container
        spacing={1}
      >
        {/* Enter amount display */}
        <Grid
          item
          md={3}
          xs={12}
        >
          <Box
            sx={{
              height: 'calc(var(--tile-h) * 2 + 8px)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              background: 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)',
              borderRadius: '10px',
              px: 2,
            }}
          >
            <Typography
              sx={{
                fontSize: 28,
                fontWeight: 900,
                color: appColors.white,
                fontVariantNumeric: 'tabular-nums',
                wordBreak: 'break-all',
              }}
            >
              {enterAmount || '0'}
            </Typography>
          </Box>
        </Grid>

        {/* Numpad */}
        <Grid
          item
          md={6}
          xs={12}
        >
          <Grid
            container
            spacing={1}
          >
            {NUMPAD_KEYS.map((key) => (
              <Grid
                item
                key={'num-' + key}
                xs={4}
              >
                <Item
                  onClick={() => addDigit(key)}
                  sx={{
                    background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
                    border: '1px solid #cbd5e1',
                    height: 'var(--tile-h)',
                  }}
                >
                  <Typography sx={{ fontWeight: 700, fontSize: 18, color: '#0F1D4D' }}>
                    {key}
                  </Typography>
                </Item>
              </Grid>
            ))}
          </Grid>
        </Grid>

        {/* Action buttons: Clear / Accept */}
        <Grid
          item
          md={3}
          xs={12}
        >
          <Grid
            container
            spacing={1}
          >
            <Grid
              item
              xs={12}
            >
              <Item
                onClick={clearAmount}
                sx={{
                  height: 'var(--tile-h)',
                  background: 'linear-gradient(135deg, #fee2e2 0%, #fecaca 100%)',
                  border: '1px solid #fca5a5',
                }}
              >
                <Typography sx={{ fontWeight: 700, fontSize: 14, color: '#991b1b' }}>
                  Clear
                </Typography>
              </Item>
            </Grid>
            <Grid
              item
              xs={12}
            >
              <Item
                onClick={acceptAmount}
                sx={{
                  height: 'var(--tile-h)',
                  background: 'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)',
                  border: '1px solid #86efac',
                }}
              >
                <Typography sx={{ fontWeight: 700, fontSize: 14, color: '#14532d' }}>
                  Accept
                </Typography>
              </Item>
            </Grid>
          </Grid>
        </Grid>
      </Grid>
    </Box>
  );
};

const AmountTile = ({
  label,
  value,
  currencyCode,
  color,
}: {
  label: string;
  value: number;
  currencyCode: string;
  color: string;
}) => (
  <Box
    sx={{
      height: 'var(--tile-h)',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'center',
      background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)',
      borderRadius: '10px',
      border: '1px solid #e2e8f0',
      px: 1,
    }}
  >
    <Typography
      sx={{
        fontSize: 10,
        fontWeight: 700,
        color: '#64748b',
        textTransform: 'uppercase',
        letterSpacing: '0.5px',
      }}
    >
      {label}
    </Typography>
    <Typography
      sx={{
        fontSize: 16,
        fontWeight: 900,
        color,
        fontVariantNumeric: 'tabular-nums',
      }}
    >
      {getPriceFormatWithoutCurrency(value)}
    </Typography>
    {currencyCode && (
      <Typography sx={{ fontSize: 9, color: '#94a3b8', fontWeight: 500 }}>
        {currencyCode}
      </Typography>
    )}
  </Box>
);

export default React.memo(ResPaymentPanel);
