import {
  Box,
  Grid,
  IconButton,
  Paper,
  Skeleton,
  Stack,
  styled,
  Typography,
} from '@mui/material';
import React, { useMemo, useState } from 'react';
import { appColors } from '../../../../theme/appColors';
import { useGetAllPendingSalesQuery } from '../../../posApi';
import { useResContext } from '../../context/ResContext';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
}));

const MAX_ROW_COUNT = 8;

interface Bill {
  id: string;
  invoiceId: string;
}

const ResPendingBills = () => {
  const { onBillSelect, selectedBillId, isLoadingDetails, isFetchingDetails } = useResContext();
  const { data, isLoading } = useGetAllPendingSalesQuery();
  const [pendingPage, setPendingPage] = useState(0);

  const billList = useMemo(() => (data?.data as Bill[]) ?? [], [data?.data]);
  const totalCount = billList.length;
  const maxPage = Math.max(0, Math.ceil(totalCount / (MAX_ROW_COUNT - 1)) - 1);

  const paginatedBills = useMemo(() => {
    const start = pendingPage * (MAX_ROW_COUNT - 1);
    return billList.slice(start, start + (MAX_ROW_COUNT - 1));
  }, [billList, pendingPage]);

  const handleClick = (bill: Bill) => {
    if (isLoadingDetails || isFetchingDetails) return;
    onBillSelect(bill.id);
  };

  return (
    <Box>
      {!isLoading && (
        <Grid
          container
          spacing={1}
        >
          {paginatedBills.map((bill) => (
            <Grid
              item
              key={bill.id}
              md={1.5}
              sm={4}
              xs={4}
            >
              <Item
                onClick={() => handleClick(bill)}
                sx={{
                  background:
                    selectedBillId === bill.id
                      ? 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)'
                      : 'linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%)',
                  cursor: 'pointer',
                  border:
                    selectedBillId === bill.id
                      ? '2px solid #d97706'
                      : '2px solid transparent',
                }}
              >
                <Stack
                  alignItems="center"
                  direction="column"
                >
                  <Typography
                    sx={{
                      fontWeight: 800,
                      fontSize: 10,
                      color: '#0F1D4D',
                      textAlign: 'center',
                      letterSpacing: '0.3px',
                    }}
                  >
                    {bill.invoiceId}
                  </Typography>
                </Stack>
              </Item>
            </Grid>
          ))}

          {/* Empty filler */}
          {Array.from(Array(MAX_ROW_COUNT - 1 - paginatedBills.length).keys()).map((k) => (
            <Grid
              item
              key={'empty-bill-' + k}
              md={1.5}
              sm={4}
              xs={4}
            >
              <Item sx={{ background: 'rgba(148,163,184,0.15)', cursor: 'default' }} />
            </Grid>
          ))}

          {/* Pagination */}
          <Grid
            item
            md={1.5}
            sm={4}
            xs={4}
          >
            <Item
              sx={{
                background: 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)',
                cursor: 'default',
              }}
            >
              <Grid container>
                <Grid
                  item
                  sm={6}
                >
                  <IconButton
                    disabled={pendingPage <= 0}
                    onClick={() => setPendingPage((p) => p - 1)}
                    size="small"
                    sx={{
                      color: appColors.white,
                      '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                    }}
                  >
                    <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
                <Grid
                  item
                  sm={6}
                >
                  <IconButton
                    disabled={pendingPage >= maxPage}
                    onClick={() => setPendingPage((p) => p + 1)}
                    size="small"
                    sx={{
                      color: appColors.white,
                      '&:disabled': { color: 'rgba(255,255,255,0.3)' },
                    }}
                  >
                    <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
              </Grid>
            </Item>
          </Grid>
        </Grid>
      )}

      {isLoading && (
        <Grid
          container
          spacing={1}
        >
          {[...Array(MAX_ROW_COUNT)].map((_, idx) => (
            <Grid
              item
              key={idx}
              md={1.5}
              sm={4}
              xs={4}
            >
              <Skeleton
                height={'var(--tile-h)'}
                sx={{ borderRadius: '10px' }}
                variant="rectangular"
              />
            </Grid>
          ))}
        </Grid>
      )}
    </Box>
  );
};

export default React.memo(ResPendingBills);
