import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React from 'react';
import { useNavigate } from 'react-router-dom';
import ShoppingBasketIcon from '@mui/icons-material/ShoppingBasket';
import SearchIcon from '@mui/icons-material/Search';
import CardGiftcardIcon from '@mui/icons-material/CardGiftcard';
import PercentIcon from '@mui/icons-material/Percent';
import NoteAltIcon from '@mui/icons-material/NoteAlt';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import StockModel from './Model/StockModel';
import DiscountModel from '../SalesLeft/Model/DiscountModel';
import ShoppingCartCheckoutIcon from '@mui/icons-material/ShoppingCartCheckout';
import RefreshIcon from '@mui/icons-material/Refresh';
import useSalesRich from '../../useSalesRich';
import { useSaveRichSalesMutation } from '../../../posApi';
import useNotifier from '../../../../core/Notifier/use-notifier';
import { useAppDispatch } from '../../../../store/hooks';
import { removeBasket, clearCustomer } from '../../store/SalesRichBasketSlice';
import BackdropLoading from '../../../../components/BackdropLoading';
import { useAppSelector } from '../../../../store/hooks';
import ConfirmationModel from '../../../../components/ModelPopup/ConfirmationModel';
import { useTranslation } from 'react-i18next';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const btnLabel = (text: string, color = '#0F1D4D') => (
  <Typography sx={{ fontWeight: 700, fontSize: 11, color, mt: '2px' }}>
    {text}
  </Typography>
);

const FifthSection = () => {
  const { t } = useTranslation(['salesRich']);
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { showErrorMessage, showMessage } = useNotifier();
  const [stockOpen, setStockOpen] = React.useState(false);
  const [openDiscount, setOpenDiscount] = React.useState(false);
  const { salesDetails } = useSalesRich();
  const [saveSales, { isLoading }] = useSaveRichSalesMutation();
  const [openBackConfirmation, setOpenBackConfirmation] = React.useState(false);
  // eslint-disable-next-line max-len
  const [openRefreshConfirmation, setOpenRefreshConfirmation] = React.useState(false);

  const basketItems = useAppSelector((state) => state.salesRichBasket.items);
  const hasItems = basketItems.length > 0;

  const handleBackToDashboard = () => navigate('/dashboard');

  const handleRefresh = () => {
    dispatch(removeBasket());
    dispatch(clearCustomer());
    setOpenRefreshConfirmation(false);
  };

  const temporarySales = async () => {
    if (!hasItems) return;
    try {
      const salesRes = await saveSales({ ...salesDetails, paymentMethod: '', isPaid: false }).unwrap();
      if (!salesRes.status) {
        showErrorMessage(salesRes.message);
      } else {
        showMessage(salesRes.message);
        dispatch(removeBasket());
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const L_TEAL   = 'linear-gradient(135deg, #ccfbf1 0%, #99f6e4 100%)';  // operational / inventory
  const L_GREEN  = 'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)';  // save / confirm
  const L_AMBER  = 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)';  // caution / discount
  const L_BLUE   = 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)';  // navigation / back
  const L_PINK   = 'linear-gradient(135deg, #fce7f3 0%, #fbcfe8 100%)';  // gift / special
  const L_INDIGO = 'linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%)';  // utility / notes

  return (
    <Box>
      <Grid
        container
        spacing={1}
      >
        {/* Stock & Price */}
        <Grid
          item
          key="fifth_1"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={() => setStockOpen(true)}
            sx={{ background: L_TEAL, position: 'relative' }}
          >
            <SearchIcon
              sx={{ fontSize: 14, color: 'rgba(15,29,77,0.4)', position: 'absolute', top: 7, right: 7 }}
            />
            <Stack
              alignItems="center"
              direction="column"
            >
              <ShoppingBasketIcon sx={{ fontSize: 26, color: '#0F8B8D' }} />
              {btnLabel('Stock & Price')}
            </Stack>
          </Item>
        </Grid>

        {/* Refresh */}
        <Grid
          item
          key="fifth_2"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            // eslint-disable-next-line max-len
            onClick={hasItems ? () => setOpenRefreshConfirmation(true) : undefined}
            // eslint-disable-next-line max-len
            sx={{ background: L_BLUE, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <RefreshIcon sx={{ fontSize: 26, color: '#1d4ed8' }} />
              {btnLabel('Refresh', '#1e3a8a')}
            </Stack>
          </Item>
        </Grid>

        {/* Save sales */}
        <Grid
          item
          key="fifth_3"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={hasItems ? temporarySales : undefined}
            sx={{ background: L_GREEN, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <ShoppingCartCheckoutIcon sx={{ fontSize: 26, color: '#16a34a' }} />
              {btnLabel('Save Sales', '#14532d')}
            </Stack>
          </Item>
        </Grid>

        {/* Gift Card */}
        <Grid
          item
          key="fifth_4"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={hasItems ? () => {} : undefined}
            sx={{ background: L_PINK, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <CardGiftcardIcon sx={{ fontSize: 26, color: '#db2777' }} />
              {btnLabel('Gift Card', '#831843')}
            </Stack>
          </Item>
        </Grid>

        {/* Discount */}
        <Grid
          item
          key="fifth_5"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={hasItems ? () => setOpenDiscount(true) : undefined}
            sx={{ background: L_AMBER, opacity: hasItems ? 1 : 0.38, cursor: hasItems ? 'pointer' : 'default' }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <PercentIcon sx={{ fontSize: 26, color: '#d97706' }} />
              {btnLabel('Discount', '#92400e')}
            </Stack>
          </Item>
        </Grid>

        {/* Filler */}
        <Grid
          item
          key="fifth_6"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            sx={{
              background: 'rgba(148,163,184,0.15)',
              cursor: 'default',
            }}
          />
        </Grid>

        {/* Notes */}
        <Grid
          item
          key="fifth_notes"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item sx={{ background: L_INDIGO }}>
            <Stack
              alignItems="center"
              direction="column"
            >
              <NoteAltIcon sx={{ fontSize: 26, color: '#4f46e5' }} />
              {btnLabel('Notes', '#312e81')}
            </Stack>
          </Item>
        </Grid>

        {/* Back */}
        <Grid
          item
          key="fifth_7"
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={() =>
              hasItems ? setOpenBackConfirmation(true) : handleBackToDashboard()
            }
            sx={{
              background: L_BLUE,
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <ArrowBackIcon sx={{ fontSize: 26, color: '#1E3A8A' }} />
              {btnLabel('Back')}
            </Stack>
          </Item>
        </Grid>
      </Grid>

      {stockOpen && <StockModel
        handleClose={() => setStockOpen(false)}
        open={stockOpen}
                    />}

      {openDiscount && (
        <DiscountModel
          handleClose={() => setOpenDiscount(false)}
          open={openDiscount}
          title="Add Discount"
        />
      )}

      {openBackConfirmation && (
        <ConfirmationModel
          content={t('salesRich:confirmBackMessage')}
          handleClose={() => setOpenBackConfirmation(false)}
          onConfirm={() => handleBackToDashboard()}
          open={openBackConfirmation}
          title={t('salesRich:confirmationBackTitle')}
        />
      )}

      {openRefreshConfirmation && (
        <ConfirmationModel
          content={t('salesRich:confirmRefreshMessage')}
          handleClose={() => setOpenRefreshConfirmation(false)}
          onConfirm={() => handleRefresh()}
          open={openRefreshConfirmation}
          title={t('salesRich:confirmRefreshTitle')}
        />
      )}

      <BackdropLoading isLoading={isLoading} />
    </Box>
  );
};

export default React.memo(FifthSection);
