import React from 'react';
import Box from '@mui/material/Box';
import Login from './Login';
import { Divider, Fade, Stack, Typography } from '@mui/material';
import { appColors } from '../../theme/appColors';
import StorefrontOutlinedIcon from '@mui/icons-material/StorefrontOutlined';
import PointOfSaleOutlinedIcon from '@mui/icons-material/PointOfSaleOutlined';
import InventoryOutlinedIcon from '@mui/icons-material/InventoryOutlined';
import BarChartOutlinedIcon from '@mui/icons-material/BarChartOutlined';
import EmailOutlinedIcon from '@mui/icons-material/EmailOutlined';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import LanguageOutlinedIcon from '@mui/icons-material/LanguageOutlined';

const STATS = [
  { value: '500+', label: 'Outlets' },
  { value: '10K+', label: 'Daily Orders' },
  { value: '99.9%', label: 'Uptime' },
];

const FEATURES = [
  { icon: <PointOfSaleOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Sales & Checkout', desc: 'Fast POS billing with multiple payment modes' },
  { icon: <StorefrontOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Multi-outlet', desc: 'Manage multiple branches from one dashboard' },
  { icon: <InventoryOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Inventory', desc: 'Real-time stock tracking and low-stock alerts' },
  { icon: <BarChartOutlinedIcon sx={{ fontSize: 16 }} />, label: 'Analytics', desc: 'Sales reports, profit trends and insights' },
];

const CONTACTS = [
  { icon: <EmailOutlinedIcon sx={{ fontSize: '0.78rem' }} />, text: 'support@allespos.com' },
  { icon: <PhoneOutlinedIcon sx={{ fontSize: '0.78rem' }} />, text: '+61 406 690 485,  +94 77 735 5075' },
  {
    icon: <WhatsAppIcon sx={{ fontSize: '0.78rem' }} />,
    text: '+61 406 690 485,  +94 77 735 5075',
    iconColor: '#25D366',
  },
  { icon: <LanguageOutlinedIcon sx={{ fontSize: '0.78rem' }} />, text: 'www.allespos.com' },
];

/* 3D POS Terminal */
const PosTerminal = () => (
  <Fade in timeout={900}>
    <Box
      sx={{
        width: { md: 118, lg: 138 },
        flexShrink: 0,
        transform: 'perspective(520px) rotateY(-16deg) rotateX(6deg)',
        filter: 'drop-shadow(0 24px 48px rgba(0,0,0,0.60))',
        transition: 'transform 0.4s ease',
        '&:hover': { transform: 'perspective(520px) rotateY(-6deg) rotateX(2deg)' },
      }}
    >
      <Box
        sx={{
          borderRadius: '14px',
          background: 'linear-gradient(150deg, #1e3a8a 0%, #1e40af 45%, #172554 100%)',
          border: '1.5px solid rgba(255,255,255,0.16)',
          p: 1.25,
          boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.12), inset 0 -2px 0 rgba(0,0,0,0.2)',
        }}
      >
        {/* Screen */}
        <Box
          sx={{
            borderRadius: '8px',
            background: 'linear-gradient(160deg, #060e24 0%, #0c1e45 100%)',
            border: '1px solid rgba(100,160,255,0.22)',
            p: 1,
            mb: 1,
          }}
        >
          <Typography sx={{ fontSize: '0.42rem', color: 'rgba(255,255,255,0.4)', letterSpacing: '0.07em', textTransform: 'uppercase', mb: 0.25 }}>
            Total Sales
          </Typography>
          <Typography sx={{ fontSize: '1rem', fontWeight: 800, color: '#fff', lineHeight: 1, mb: 0.6 }}>
            $12,580
          </Typography>
          {/* Bar chart */}
          <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: '2px', height: 18 }}>
            {[40, 58, 44, 72, 62, 88, 76].map((h, i) => (
              <Box
                key={i}
                sx={{
                  flex: 1,
                  height: `${h}%`,
                  borderRadius: '2px',
                  background: i === 5
                    ? 'rgba(99,179,255,0.95)'
                    : 'rgba(99,150,255,0.32)',
                }}
              />
            ))}
          </Box>
        </Box>
        {/* Keypad */}
        <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: '3px', mb: 0.75 }}>
          {['1','2','3','4','5','6','7','8','9','*','0','↵'].map((k) => (
            <Box
              key={k}
              sx={{
                height: 11,
                borderRadius: '3px',
                background: 'rgba(255,255,255,0.08)',
                border: '1px solid rgba(255,255,255,0.06)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <Typography sx={{ fontSize: '0.38rem', color: 'rgba(255,255,255,0.45)' }}>{k}</Typography>
            </Box>
          ))}
        </Box>
        {/* Card slot */}
        <Box
          sx={{
            height: 6,
            borderRadius: '3px',
            background: 'rgba(0,0,0,0.35)',
            border: '1px solid rgba(255,255,255,0.06)',
            position: 'relative',
            overflow: 'hidden',
          }}
        >
          <Box sx={{ position: 'absolute', top: '30%', left: '18%', right: '18%', height: '40%', borderRadius: '1px', background: 'rgba(255,255,255,0.10)' }} />
        </Box>
      </Box>
    </Box>
  </Fade>
);

/* 3D floating sales metric card */
const SalesCard = () => (
  <Fade in timeout={1050}>
    <Box
      sx={{
        width: { md: 108, lg: 124 },
        flexShrink: 0,
        transform: 'perspective(520px) rotateY(12deg) rotateX(-5deg)',
        filter: 'drop-shadow(0 18px 40px rgba(0,0,0,0.52))',
        transition: 'transform 0.4s ease',
        '&:hover': { transform: 'perspective(520px) rotateY(4deg) rotateX(-2deg)' },
      }}
    >
      <Box
        sx={{
          borderRadius: '12px',
          background: 'rgba(255,255,255,0.07)',
          backdropFilter: 'blur(18px)',
          border: '1.5px solid rgba(255,255,255,0.16)',
          p: 1.25,
          boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.12)',
        }}
      >
        {/* Header */}
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.6 }}>
          <Typography sx={{ fontSize: '0.42rem', color: 'rgba(255,255,255,0.42)', textTransform: 'uppercase', letterSpacing: '0.07em' }}>
            Orders Today
          </Typography>
          <Box
            sx={{
              px: 0.6,
              py: 0.2,
              borderRadius: '6px',
              background: 'rgba(74,222,128,0.14)',
              border: '1px solid rgba(74,222,128,0.28)',
            }}
          >
            <Typography sx={{ fontSize: '0.38rem', color: '#4ade80', fontWeight: 700 }}>↑ 14%</Typography>
          </Box>
        </Box>
        <Typography sx={{ fontSize: '1.1rem', fontWeight: 800, color: '#fff', lineHeight: 1, mb: 0.65 }}>
          248
        </Typography>
        {/* Sparkline */}
        <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: '2px', height: 18, mb: 0.75 }}>
          {[50, 65, 52, 82, 70, 92, 84].map((h, i) => (
            <Box
              key={i}
              sx={{
                flex: 1,
                height: `${h}%`,
                borderRadius: '2px',
                background: i === 5
                  ? 'rgba(74,222,128,0.85)'
                  : 'rgba(74,222,128,0.24)',
              }}
            />
          ))}
        </Box>
        <Box sx={{ height: '1px', background: 'rgba(255,255,255,0.08)', mb: 0.75 }} />
        {/* Revenue row */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 0.5 }}>
          <Typography sx={{ fontSize: '0.4rem', color: 'rgba(255,255,255,0.34)' }}>Revenue</Typography>
          <Typography sx={{ fontSize: '0.5rem', fontWeight: 700, color: 'rgba(255,255,255,0.72)' }}>$8,240</Typography>
        </Box>
        {/* Status dots */}
        <Box sx={{ display: 'flex', gap: 0.4, alignItems: 'center' }}>
          <Box sx={{ width: 5, height: 5, borderRadius: '50%', background: '#4ade80', boxShadow: '0 0 5px #4ade80' }} />
          <Typography sx={{ fontSize: '0.4rem', color: 'rgba(255,255,255,0.35)' }}>System live</Typography>
        </Box>
      </Box>
    </Box>
  </Fade>
);

const Auth = () => {
  return (
    <Box
      data-testid="Terms and condition Page"
      sx={{ height: '100vh', display: 'flex', overflow: 'hidden' }}
    >
      {/* ══════════════════ LEFT PANEL (3/5) ══════════════════ */}
      <Box
        sx={{
          display: { xs: 'none', md: 'flex' },
          flex: '0 0 60%',
          flexDirection: 'column',
          position: 'relative',
          overflow: 'hidden',
          background: `
            radial-gradient(ellipse at 18% 12%, rgba(90,120,255,0.42) 0%, transparent 48%),
            radial-gradient(ellipse at 82% 88%, rgba(8,14,70,0.60) 0%, transparent 48%),
            radial-gradient(ellipse at 70% 5%,  rgba(40,60,200,0.25) 0%, transparent 42%),
            linear-gradient(148deg, ${appColors.reflexBlue[100]} 0%, #0d1870 50%, #060c3e 100%)
          `,
        }}
      >
        {/* Grid overlay */}
        <Box
          sx={{
            position: 'absolute', inset: 0, pointerEvents: 'none',
            backgroundImage: `
              linear-gradient(rgba(255,255,255,0.018) 1px, transparent 1px),
              linear-gradient(90deg, rgba(255,255,255,0.018) 1px, transparent 1px)
            `,
            backgroundSize: '52px 52px',
          }}
        />
        {/* Glow orbs */}
        <Box sx={{ position: 'absolute', top: '-16%', right: '-6%', width: 500, height: 500, borderRadius: '50%', background: 'radial-gradient(circle, rgba(80,120,255,0.16) 0%, transparent 65%)', pointerEvents: 'none' }} />
        <Box sx={{ position: 'absolute', bottom: '-12%', left: '-6%', width: 380, height: 380, borderRadius: '50%', background: 'radial-gradient(circle, rgba(40,70,200,0.14) 0%, transparent 65%)', pointerEvents: 'none' }} />

        {/* Content column */}
        <Box
          sx={{
            position: 'relative',
            zIndex: 1,
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            px: { md: 5, lg: 7 },
            pt: { md: 4, lg: 5 },
            pb: { md: 3.5, lg: 4.5 },
            gap: { md: 2, lg: 2.5 },
            justifyContent: 'space-between',
          }}
        >

          {/* ── 1. Logo ── */}
          <Fade in timeout={600}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.25, flex: '0 0 auto' }}>
              <Box
                component="img"
                src="/images/logo.png"
                sx={{ height: { md: 32, lg: 36 }, width: 'auto', filter: 'brightness(0) invert(1)' }}
              />
              <Box
                sx={{
                  px: 1.1, py: 0.3,
                  borderRadius: '14px',
                  background: 'rgba(255,255,255,0.10)',
                  border: '1px solid rgba(255,255,255,0.18)',
                }}
              >
                <Typography sx={{ fontSize: '0.58rem', fontWeight: 700, letterSpacing: '0.09em', color: 'rgba(255,255,255,0.80)', textTransform: 'uppercase' }}>
                  Point of Sale
                </Typography>
              </Box>
            </Box>
          </Fade>

          {/* ── 2. Headline + Screenshots (same row) ── */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: { md: 2, lg: 3 }, flex: '0 0 auto' }}>

            {/* Headline text — left side */}
            <Fade in timeout={750}>
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Typography
                  sx={{
                    fontSize: { md: '1.8rem', lg: '2.3rem', xl: '2.7rem' },
                    fontWeight: 800,
                    color: '#fff',
                    lineHeight: 1.12,
                    letterSpacing: '-0.03em',
                    mb: 1.25,
                  }}
                >
                  Smarter Sales.
                  <br />
                  <Box component="span" sx={{ color: 'rgba(155,185,255,0.95)' }}>
                    Faster Growth.
                  </Box>
                </Typography>
                <Typography
                  sx={{
                    fontSize: { md: '0.78rem', lg: '0.85rem' },
                    color: 'rgba(255,255,255,0.46)',
                    lineHeight: 1.75,
                  }}
                >
                  Your all-in-one POS platform — manage sales, inventory and analytics from one powerful dashboard.
                </Typography>
              </Box>
            </Fade>

            {/* 3D POS illustrations — right side */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: { md: 1.5, lg: 2 }, flexShrink: 0 }}>
              <PosTerminal />
              <SalesCard />
            </Box>

          </Box>

          {/* ── 4. Stats ── */}
          <Fade in timeout={1000}>
            <Box
              sx={{
                display: 'flex',
                gap: { md: 1, lg: 1.5 },
                flex: '0 0 auto',
              }}
            >
              {STATS.map(({ value, label }) => (
                <Box
                  key={label}
                  sx={{
                    flex: 1,
                    px: { md: 1.5, lg: 2 },
                    py: { md: 1.25, lg: 1.5 },
                    borderRadius: '12px',
                    background: 'rgba(255,255,255,0.06)',
                    border: '1px solid rgba(255,255,255,0.10)',
                    textAlign: 'center',
                  }}
                >
                  <Typography sx={{ fontSize: { md: '1.25rem', lg: '1.5rem' }, fontWeight: 800, color: '#fff', lineHeight: 1 }}>
                    {value}
                  </Typography>
                  <Typography sx={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.42)', mt: 0.4, fontWeight: 500 }}>
                    {label}
                  </Typography>
                </Box>
              ))}
            </Box>
          </Fade>

          {/* ── 5. Feature tiles (with description) ── */}
          <Fade in timeout={1100}>
            <Box
              sx={{
                display: 'grid',
                gridTemplateColumns: '1fr 1fr',
                gap: { md: 0.75, lg: 1 },
                flex: '0 0 auto',
              }}
            >
              {FEATURES.map(({ icon, label, desc }) => (
                <Box
                  key={label}
                  sx={{
                    px: { md: 1.25, lg: 1.5 },
                    py: { md: 1, lg: 1.25 },
                    borderRadius: '10px',
                    background: 'rgba(255,255,255,0.06)',
                    border: '1px solid rgba(255,255,255,0.09)',
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.4 }}>
                    <Box sx={{ color: 'rgba(160,185,255,0.85)', display: 'flex' }}>{icon}</Box>
                    <Typography sx={{ fontSize: '0.78rem', fontWeight: 700, color: 'rgba(255,255,255,0.80)' }}>
                      {label}
                    </Typography>
                  </Box>
                  <Typography sx={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.38)', lineHeight: 1.5, pl: 0.25 }}>
                    {desc}
                  </Typography>
                </Box>
              ))}
            </Box>
          </Fade>

          {/* ── 6. Contact + copyright ── */}
          <Fade in timeout={1200}>
            <Box sx={{ flex: '0 0 auto' }}>
              <Divider sx={{ borderColor: 'rgba(255,255,255,0.09)', mb: 2 }} />
              <Box sx={{ display: 'flex', flexWrap: 'wrap', columnGap: { md: 2, lg: 2.5 }, rowGap: 0.85 }}>
                {CONTACTS.map(({ icon, text, iconColor }) => (
                  <Stack
                    alignItems="center"
                    direction="row"
                    key={text + (iconColor ?? '')}
                    spacing={0.65}
                  >
                    <Box sx={{ color: iconColor ?? 'rgba(255,255,255,0.36)', display: 'flex' }}>{icon}</Box>
                    <Typography sx={{ color: 'rgba(255,255,255,0.36)', fontSize: '0.7rem' }}>
                      {text}
                    </Typography>
                  </Stack>
                ))}
              </Box>
              <Typography sx={{ mt: 1.5, color: 'rgba(255,255,255,0.16)', fontSize: '0.63rem' }}>
                © {new Date().getFullYear()} Alles POS. All rights reserved.
              </Typography>
            </Box>
          </Fade>

        </Box>
      </Box>

      {/* ══════════════════ RIGHT PANEL (2/5) ══════════════════ */}
      <Box
        sx={{
          flex: '0 0 40%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative',
          overflow: 'hidden',
          background: `
            radial-gradient(ellipse at 75% 8%,  rgba(200,215,255,0.38) 0%, transparent 55%),
            radial-gradient(ellipse at 25% 92%, rgba(180,200,255,0.22) 0%, transparent 52%),
            linear-gradient(168deg, #EEF2FF 0%, #F4F6FF 55%, #FFFFFF 100%)
          `,
          px: { xs: 3, sm: 5, md: 4, lg: 6 },
        }}
      >
        <Box sx={{ position: 'absolute', top: -90, right: -90, width: 280, height: 280, borderRadius: '50%', background: 'radial-gradient(circle, rgba(180,200,255,0.28) 0%, transparent 70%)', pointerEvents: 'none' }} />
        <Box sx={{ position: 'absolute', bottom: -70, left: -70, width: 240, height: 240, borderRadius: '50%', background: 'radial-gradient(circle, rgba(200,215,255,0.22) 0%, transparent 70%)', pointerEvents: 'none' }} />

        {/* Mobile logo */}
        <Box sx={{ display: { xs: 'flex', md: 'none' }, justifyContent: 'center', position: 'absolute', top: 32 }}>
          <Box
            component="img"
            src="/images/logo.png"
            sx={{ height: 44, width: 'auto', objectFit: 'contain' }}
          />
        </Box>

        <Login />
      </Box>
    </Box>
  );
};

export default Auth;
