import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  Checkbox,
  FormControlLabel,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useFormik } from 'formik';
import { useMemo } from 'react';
import { IAddCount } from '../../../core/Interface/property.interface';
import { useAppDispatch } from '../../../store/hooks';
import { updateProductCount } from '../store/BasketSlice';

interface IAddCountProb {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  item?: IAddCount;
}

const AddItemCount = ({
  title,
  openModel = false,
  handleCloseDialog,
  maxDiscountAmount,
  item,
}: IAddCountProb & { maxDiscountAmount: number }) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const dispatch = useAppDispatch();

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const maxDiscount = useMemo(() => {
    return item?.unitPrice ?? 0;
  }, [item]);

  const formik = useFormik({
    initialValues: {
      count: item?.count,
      discount: item?.discountValue ?? 0,
      discountAsPercentage: item?.isDiscountPercentage ?? false,
      givenPrice:
      item?.unitPrice && item?.discountValue
        ? Math.max(item.unitPrice - item.discountValue, 0)
        : 0,
    isGivenPrice: !!item?.discountValue && !item?.isDiscountPercentage,
    },
    onSubmit: async (values) => {
      let discountValue = values.discount || 0;
      if (values.isGivenPrice && item?.unitPrice !== undefined) {
        discountValue = item.unitPrice - values.givenPrice;
      }

      if (discountValue >= 0 && item) {
        const itemCount: IAddCount = {
          code: item.code || '',
          count: values.count || 1,
          discountValue: discountValue,
          isDiscountPercentage: values.discountAsPercentage || false,
          id: item.id || '',
        };
        dispatch(updateProductCount(itemCount));
      }

      handleClose();
    },

    validate: (values) => {
      const errors: Partial<typeof values> = {};

      if (!values.isGivenPrice) {
        if (
          values.discount &&
          item?.unitPrice &&
          values.discount > (maxDiscountAmount / item?.unitPrice) * 100
        ) {
          errors.discount = maxDiscountAmount;
        }
      } else {
        if (
          values.givenPrice &&
          values.givenPrice < maxDiscount - maxDiscountAmount
        ) {
          errors.discount = maxDiscountAmount;
        }
      }

      return errors;
    },
  });

  const formValid = useMemo(() => {
    if (formik.values.isGivenPrice) {
      return (
        formik.values.count !== undefined &&
        formik.values.count > 0 &&
        !formik.errors.discount &&
        (item?.unitPrice !== undefined
          ? formik.values.givenPrice <= item.unitPrice
          : true)
      );
    } else {
      const discountAmount = formik.values.discountAsPercentage
        ? ((formik.values.discount ?? 0) / 100) * (item?.unitPrice ?? 0)
        : formik.values.discount || 0;
      return (
        formik.values.count !== undefined &&
        formik.values.count > 0 &&
        discountAmount <= maxDiscountAmount &&
        !formik.errors.discount &&
        discountAmount >= 0 &&
        item !== undefined
      );
    }
  }, [formik.values, formik.errors, maxDiscountAmount, item]);

  React.useEffect(() => {
    if (!formik.values.isGivenPrice) {
      formik.setFieldValue('givenPrice', 0, false);
    } else {
      formik.setFieldValue('discount', 0, false);
      formik.setFieldValue('discountAsPercentage', false, false);
    }

    if (!formik.values.discountAsPercentage) {
      formik.setFieldValue('discount', 0, false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    formik.values.discountAsPercentage,
    formik.values.isGivenPrice,
    formik.values.givenPrice,
    item,
  ]);

  return (
    <div>
      <form onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="xs"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <EditOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Update item details</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
            {formValid ? null : (
              <Typography
                sx={{
                  color: 'error.main',
                  textAlign: 'center',
                  fontWeight: 700,
                }}
              >
                Please check your discount (Maximum discount:{' '}
                {maxDiscountAmount})
              </Typography>
            )}
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={'Count'} />
                  <TextField
                    autoComplete="off"
                    placeholder="Count"
                    size="small"
                    {...formik.getFieldProps('count')}
                    InputProps={{ inputProps: { min: 1 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    type="number"
                  />
                </GridItem>

                <GridItem>
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={formik.values.isGivenPrice}
                        {...formik.getFieldProps('isGivenPrice')}
                        //disabled={formik.values.discountAsPercentage}
                      />
                    }
                    label="Are you going to use given Price"
                    sx={{ pt: 2 }}
                  />
                </GridItem>

                {formik.values.isGivenPrice && (
                  <GridItem
                    lg={6}
                    sm={6}
                    sx={{ pt: 2 }}
                    xs={6}
                  >
                    <FieldHeader title={'Discount Price'} />
                    <TextField
                      autoComplete="off"
                      placeholder="Given Price"
                      size="small"
                      {...formik.getFieldProps('givenPrice')}
                      InputProps={{
                        inputProps: { min: 0 },
                      }}
                      sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                      type="number"
                      //disabled={formik.values.discountAsPercentage}
                    />
                  </GridItem>
                )}

                {!formik.values.isGivenPrice && (
                  <>
                    <GridItem
                      lg={6}
                      sm={6}
                      sx={{ pt: 2 }}
                      xs={6}
                    >
                      <FieldHeader title={'Discount'} />
                      <TextField
                        autoComplete="off"
                        placeholder="Discount"
                        size="small"
                        {...formik.getFieldProps('discount')}
                        InputProps={{ inputProps: { min: 1 } }}
                        sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                        type="number"
                        //disabled={formik.values.isGivenPrice}
                      />
                    </GridItem>
                    <GridItem
                      lg={6}
                      sm={6}
                      xs={6}
                    >
                      <FormControlLabel
                        control={
                          <Checkbox
                            checked={formik.values.discountAsPercentage}
                            {...formik.getFieldProps('discountAsPercentage')}
                            //disabled={formik.values.isGivenPrice}
                          />
                        }
                        label="Is Percentage (%)"
                        sx={{ pt: 5, pl: 2 }}
                      />
                    </GridItem>
                  </>
                )}
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
              variant="outlined"
            >
              Cancel
            </Button>
            <Button
              autoFocus
              disabled={!formValid}
              onClick={() => { formik.handleSubmit(); }}
              sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
              type="submit"
              variant="contained"
            >
              Update
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(AddItemCount);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
