import { Box, CircularProgress, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React from 'react';
import { useNavigate } from 'react-router-dom';
import PercentIcon from '@mui/icons-material/Percent';
import RefreshIcon from '@mui/icons-material/Refresh';
import BorderColorIcon from '@mui/icons-material/BorderColor';
import PaymentIcon from '@mui/icons-material/Payment';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { useAppDispatch } from '../../../../store/hooks';
import { removeBasket, addFinalSummaryState } from '../../store/BasketSlice';
import { useResContext } from '../../context/ResContext';
import useSales from '../../useSales';
import SalesDiscount from '../SalesDiscount';
import {
  useGetUserQuery,
  useSaveResSalesMutation,
  useSaveSalesMutation,
} from '../../../posApi';
import { useNotifier } from '../../../../core/Notifier';
import { Invoice } from '../Invoice';
import { useReactToPrint } from 'react-to-print';
import { ISalesReceipt } from '../../../../core/Interface/sale.interface';
import { selectPaymentMethod } from '../../store/BasketSelector';
import store from '../../../../store';
import { calculateFontSize } from '../../../../core/utils';
import { IUserInfo } from '../../../../core/Interface/user.interface';
import AlertPopup from '../../../../components/ModelPopup/AlertPopup';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const btnLabel = (text: string, color = '#0F1D4D') => (
  <Typography sx={{ fontWeight: 700, fontSize: 11, color, mt: '2px' }}>
    {text}
  </Typography>
);

const EMPTY_RECEIPT: ISalesReceipt = {
  headerText1: '',
  headerText2: '',
  headerText3: '',
  mobile: '',
  email: '',
  footerText1: '',
  footerText2: '',
  footerText3: '',
  logo: '',
  invoiceId: '',
  customerName: '',
  saleBy: '',
  dateTime: '',
  isDiscountPercentage: false,
  discountValue: 0,
  discount: 0,
  totalDiscount: 0,
  total: 0,
  subTotal: 0,
  received: 0,
  balance: 0,
  return: 0,
  paymentMethod: '',
  items: [
    {
      productId: '',
      qty: 0,
      unitPrice: 0,
      amount: 0,
      isDiscountPercentage: false,
      discountValue: 0,
      discount: 0,
      amountAfterDiscount: 0,
      productName: '',
    },
  ],
};

const ResActionRow = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { onClear, invoiceId, salesList } = useResContext();
  const { salesDetails, paymentStatus, selectItem } = useSales();
  const { showErrorMessage, showMessage } = useNotifier();

  const [openDiscount, setOpenDiscount] = React.useState(false);
  const [openAlert, setOpenAlert] = React.useState(false);
  const [response, setResponse] = React.useState<ISalesReceipt>(EMPTY_RECEIPT);

  const [saveSales, { isLoading: isSalesLoading }] = useSaveSalesMutation();
  const [saveResSales, { isLoading: isResLoading }] = useSaveResSalesMutation();

  const { data: companyData } = useGetUserQuery();

  const printPaperSizeInPixel = React.useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.branch.printPaperSizeInPixel) {
        return Number(userData.branch.printPaperSizeInPixel);
      }
    }
    return 10;
  }, [companyData]);

  const componentRef = React.useRef<HTMLDivElement | null>(null);
  const handlePrint = useReactToPrint({
    content: () => componentRef.current,
  });

  const handlePay = async () => {
    try {
      const salesRes = await saveSales({
        ...salesDetails,
        paymentMethod: selectPaymentMethod(store.getState()),
        isPaid: false,
      }).unwrap();
      if (!salesRes.status) {
        showErrorMessage(salesRes.message);
      } else {
        setResponse(salesRes.data as ISalesReceipt);
        showMessage(salesRes.message);
        setTimeout(() => handlePrint(), 200);
        dispatch(removeBasket());
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const handleFinish = async () => {
    try {
      const salesRes = await saveResSales({
        saleId: invoiceId.split('_')[0],
        received: salesDetails.balance || 0,
      }).unwrap();
      if (!salesRes.status) {
        showErrorMessage(salesRes.message);
      } else {
        const total = salesList?.total ?? 0;
        const balance = salesDetails.balance - total;
        setResponse({
          ...(salesRes.data as ISalesReceipt),
          balance,
        });
        showMessage(salesRes.message);
        setTimeout(() => handlePrint(), 200);
        onClear();
        dispatch(removeBasket());
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const handleOrder = async () => {
    if (paymentStatus && salesDetails.balance - (salesList?.total ?? 0) < 0) {
      setOpenAlert(true);
      return;
    }
    if (paymentStatus) {
      await handleFinish();
    } else {
      await handlePay();
    }
  };

  const hasItems = selectItem.length > 0;

  return (
    <Box>
      <div style={{ display: 'none' }}>
        <Invoice
          fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
          label={calculateFontSize(printPaperSizeInPixel).label}
          ref={componentRef}
          salesRes={response}
          width={printPaperSizeInPixel}
        />
      </div>

      <Grid
        container
        spacing={1}
      >
        {/* Discount */}
        <Grid
          item
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={hasItems ? () => setOpenDiscount(true) : undefined}
            sx={{
              background: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)',
              opacity: hasItems ? 1 : 0.38,
              cursor: hasItems ? 'pointer' : 'default',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <PercentIcon sx={{ fontSize: 26, color: '#d97706' }} />
              {btnLabel('Discount', '#92400e')}
            </Stack>
          </Item>
        </Grid>

        {/* Clear */}
        <Grid
          item
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={
              hasItems
                ? () => {
                    dispatch(removeBasket());
                    onClear();
                  }
                : undefined
            }
            sx={{
              background: 'linear-gradient(135deg, #fee2e2 0%, #fecaca 100%)',
              opacity: hasItems ? 1 : 0.38,
              cursor: hasItems ? 'pointer' : 'default',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <RefreshIcon sx={{ fontSize: 26, color: '#DC2626' }} />
              {btnLabel('Clear', '#991b1b')}
            </Stack>
          </Item>
        </Grid>

        {/* Filler tiles */}
        {[1, 2, 3, 4].map((k) => (
          <Grid
            item
            key={'action-filler-' + k}
            md={1.5}
            sm={4}
            xs={4}
          >
            <Item
              sx={{
                background: 'rgba(148,163,184,0.15)',
                cursor: 'default',
              }}
            />
          </Grid>
        ))}

        {/* Back */}
        <Grid
          item
          md={1.5}
          sm={4}
          xs={4}
        >
          <Item
            onClick={() => navigate('/dashboard')}
            sx={{
              background: 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <ArrowBackIcon sx={{ fontSize: 26, color: '#1E3A8A' }} />
              {btnLabel('Back')}
            </Stack>
          </Item>
        </Grid>

        {/* Order / Pay */}
        <Grid
          item
          md={3}
          sm={4}
          xs={4}
        >
          <Item
            onClick={hasItems || paymentStatus ? handleOrder : undefined}
            sx={{
              background:
                hasItems || paymentStatus
                  ? 'linear-gradient(135deg, #0F8B8D 0%, #0F1D4D 100%)'
                  : 'rgba(148,163,184,0.25)',
              opacity: hasItems || paymentStatus ? 1 : 0.35,
              cursor: hasItems || paymentStatus ? 'pointer' : 'default',
              boxShadow:
                hasItems || paymentStatus
                  ? '0 4px 14px rgba(15,139,141,0.35)'
                  : 'none',
            }}
          >
            {isSalesLoading || isResLoading ? (
              <CircularProgress
                size={24}
                sx={{ color: 'white' }}
              />
            ) : (
              <Stack
                alignItems="center"
                direction="row"
                spacing={1}
              >
                <PaymentIcon sx={{ fontSize: 28, color: '#fff' }} />
                <Typography
                  sx={{
                    fontWeight: 900,
                    fontSize: 18,
                    color: '#fff',
                    letterSpacing: '0.5px',
                  }}
                >
                  {paymentStatus ? 'PAY' : 'ORDER'}
                </Typography>
              </Stack>
            )}
          </Item>
        </Grid>

        {/* Discount dialog (shown only when !paymentStatus) */}
        {!paymentStatus && (
          <Grid
            item
            md={1.5}
            sm={4}
            xs={4}
          >
            <Item
              onClick={() =>
                dispatch(addFinalSummaryState({ finalSummaryStare: true }))
              }
              sx={{
                background: 'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)',
              }}
            >
              <Stack
                alignItems="center"
                direction="column"
              >
                <BorderColorIcon sx={{ fontSize: 26, color: '#16a34a' }} />
                {btnLabel('Bill Pay', '#14532d')}
              </Stack>
            </Item>
          </Grid>
        )}
      </Grid>

      {openDiscount && (
        <SalesDiscount
          handleCloseDialog={() => setOpenDiscount(false)}
          openModel={openDiscount}
          title="Add Discount"
        />
      )}

      <AlertPopup
        handleCloseAlert={() => setOpenAlert(false)}
        open={openAlert}
      />
    </Box>
  );
};

export default React.memo(ResActionRow);
